def transform(grid):
    h = len(grid)
    sections = []
    for r, row in enumerate(grid):
        color = row[0]
        if color not in (0, 5, 9) and all(v == color for v in row):
            sections.append((r, color))
    heights = []
    for i, (start, color) in enumerate(sections):
        end = sections[i + 1][0] if i + 1 < len(sections) else h
        heights.append(sum(color in grid[r] for r in range(start + 1, end)))
    tallest = max(range(len(heights)), key=lambda i: heights[i])
    result = []
    for i, (_, color) in enumerate(sections):
        filled = (heights[i] + 1) // 2
        result.append([color] * filled + [0] * (3 - filled) + [9, 5 if i == tallest else 0])
    return result
